Commit:     Kai Engert <kaie@kuix.de>
CommitDate: Wed Jul 23 17:56:14 2025 +0200

    Bug 1968626 - Close security info popup when clicking a button inside it. r=darktrojan


    Based on an initial patch from mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D256440

diff --git a/mail/base/content/msgSecurityPane.inc.xhtml b/mail/base/content/msgSecurityPane.inc.xhtml
index 03468418823..364186a9fc8 100644
--- a/mail/base/content/msgSecurityPane.inc.xhtml
+++ b/mail/base/content/msgSecurityPane.inc.xhtml
@@ -28,7 +28,7 @@
               <button id="openpgpImportButton"
                       class="button-focusable"
                       data-l10n-id="openpgp-import-sender-key"
-                      oncommand="Enigmail.msg.importAttachedSenderKey();"/>
+                      oncommand="event.target.closest('panel').hidePopup(); Enigmail.msg.importAttachedSenderKey();"/>
             </hbox>
           </hbox>

@@ -42,7 +42,7 @@
               <description data-l10n-id="openpgp-missing-signature-key"/>
               <button data-l10n-id="openpgp-search-signature-key"
                       class="button-focusable"
-                      oncommand="Enigmail.msg.searchSignatureKey();"/>
+                      oncommand="event.target.closest('panel').hidePopup(); Enigmail.msg.searchSignatureKey();"/>
             </hbox>
           </hbox>
         </vbox>
@@ -70,7 +70,7 @@
           <hbox pack="end">
             <button id="signatureCertView" label="&signatureCert.label;"
                     class="button-focusable"
-                    oncommand="viewSignatureCert()" />
+                    oncommand="viewSignatureCert(event.target.closest('panel'))" />
           </hbox>
         </vbox>

@@ -79,7 +79,7 @@
           <label id="signatureKeyId" flex="1" context="simpleCopyPopup"/>
           <button id="viewSignatureKey" data-l10n-id="openpgp-view-signer-key"
                   class="button-focusable"
-                  oncommand="viewSignatureKey()" collapsed="true"/>
+                  oncommand="viewSignatureKey(event.target.closest('panel'))" collapsed="true"/>
         </hbox>

         <label id="encryptionLabel" class="message-security-label"/>
@@ -91,7 +91,7 @@
                   hidden="true"
                   data-l10n-id="debug-log-title"
                   class="button-focusable"
-                  oncommand="Enigmail.msg.viewPacketDump()" />
+                  oncommand="event.target.closest('panel').hidePopup(); Enigmail.msg.viewPacketDump()" />
         </hbox>

         <vbox id="encryptionCert" class="message-security-container"
@@ -114,7 +114,7 @@
           <hbox pack="end">
             <button id="encryptionCertView" label="&encryptionCert.label;"
                     class="button-focusable"
-                    oncommand="viewEncryptionCert()" />
+                    oncommand="viewEncryptionCert(event.target.closest('panel'))" />
           </hbox>
         </vbox>

@@ -125,7 +125,7 @@
             <button id="viewEncryptionKey"
                     data-l10n-id="openpgp-view-your-encryption-key"
                     class="button-focusable"
-                    oncommand="viewEncryptionKey()"
+                    oncommand="viewEncryptionKey(event.target.closest('panel'))"
                     collapsed="true"/>
           </hbox>
         </vbox>
diff --git a/mail/base/content/msgSecurityPane.js b/mail/base/content/msgSecurityPane.js
index 4048eb6bb9b..7e69dc3e119 100644
--- a/mail/base/content/msgSecurityPane.js
+++ b/mail/base/content/msgSecurityPane.js
@@ -21,9 +21,6 @@ ChromeUtils.defineESModuleGetters(this, {
   EnigmailWindows: "chrome://openpgp/content/modules/windows.sys.mjs",
 });

-var gSigKeyId = null;
-var gEncKeyId = null;
-
 /**
  * Reveal message security popup panel with updated OpenPGP or S/MIME info.
  */
@@ -69,10 +66,6 @@ function showMessageSecurityPanel() {
  * Reset all values and clear the text of the message security popup panel.
  */
 function onMessageSecurityPopupHidden() {
-  // Clear the variables for signature and encryption.
-  gSigKeyId = null;
-  gEncKeyId = null;
-
   // Hide the UI elements.
   document.getElementById("signatureHeader").collapsed = true;
   document.getElementById("encryptionHeader").collapsed = true;
@@ -91,21 +84,31 @@ function onMessageSecurityPopupHidden() {
   }
 }

-async function viewSignatureKey() {
-  if (!gSigKeyId) {
-    return;
+async function viewSignatureKey(popupToHide) {
+  if (popupToHide) {
+    popupToHide.hidePopup();
   }

   // If the signature acceptance was edited, reload the current message.
-  if (await EnigmailWindows.openKeyDetails(window, gSigKeyId, false)) {
+  if (
+    await EnigmailWindows.openKeyDetails(
+      window,
+      Enigmail.hdrView.msgSignatureKeyId,
+      false
+    )
+  ) {
     ReloadMessage();
   }
 }

-function viewEncryptionKey() {
-  if (!gEncKeyId) {
-    return;
+function viewEncryptionKey(popupToHide) {
+  if (popupToHide) {
+    popupToHide.hidePopup();
   }

-  EnigmailWindows.openKeyDetails(window, gEncKeyId, false);
+  EnigmailWindows.openKeyDetails(
+    window,
+    Enigmail.hdrView.msgEncryptionKeyId.keyId,
+    false
+  );
 }
diff --git a/mail/extensions/openpgp/content/ui/enigmailMessengerOverlay.js b/mail/extensions/openpgp/content/ui/enigmailMessengerOverlay.js
index b3e18627a3a..d9b50bfa787 100644
--- a/mail/extensions/openpgp/content/ui/enigmailMessengerOverlay.js
+++ b/mail/extensions/openpgp/content/ui/enigmailMessengerOverlay.js
@@ -2683,7 +2683,6 @@ Enigmail.msg = {

       if (sigKeyInfo) {
         document.getElementById("viewSignatureKey").collapsed = false;
-        gSigKeyId = Enigmail.hdrView.msgSignatureKeyId;
       }
     }

@@ -2721,7 +2720,6 @@ Enigmail.msg = {
         EnigmailKeyRing.getKeyById(Enigmail.hdrView.msgEncryptionKeyId.keyId)
       ) {
         document.getElementById("viewEncryptionKey").collapsed = false;
-        gEncKeyId = Enigmail.hdrView.msgEncryptionKeyId.keyId;
       }
     }

diff --git a/mailnews/extensions/smime/msgReadSMIMEOverlay.js b/mailnews/extensions/smime/msgReadSMIMEOverlay.js
index 6f3c26e7aae..f41d274adcf 100644
--- a/mailnews/extensions/smime/msgReadSMIMEOverlay.js
+++ b/mailnews/extensions/smime/msgReadSMIMEOverlay.js
@@ -242,13 +242,21 @@ async function viewCert(cert) {
   mail3PaneWindow.switchToTabHavingURI(url, true, {});
 }

-async function viewSignatureCert() {
+async function viewSignatureCert(popupToHide) {
+  if (popupToHide) {
+    popupToHide.hidePopup();
+  }
+
   if (gSignerCert) {
     viewCert(gSignerCert);
   }
 }

-function viewEncryptionCert() {
+function viewEncryptionCert(popupToHide) {
+  if (popupToHide) {
+    popupToHide.hidePopup();
+  }
+
   if (gEncryptionCert) {
     viewCert(gEncryptionCert);
   }
